#include "group-manager.h"
#include "ns3/core-module.h"
#include "ns3/network-module.h"
#include <filesystem>
#include <fstream>
using namespace ns3;
struct Test {
 std::string out,scenario="same-source",fault;uint32_t bytes=16384,window=1000;bool pressure=false,injected=false;
 std::vector<Ptr<Node>> nodes;lightweight::GroupManager manager;
 struct Child {uint32_t task,group,src,dst,jid;Ptr<UbTransportChannel> tx,rx;Ptr<UbJetty> jetty;uint32_t admitted=0,covered=0;std::map<uint32_t,uint32_t> offsets;std::set<uint32_t> seen;bool ready=false,done=false;std::vector<uint8_t> data;};
 std::map<uint32_t,Child> children;std::map<uint32_t,std::vector<uint8_t>> payload;std::map<uint32_t,std::vector<uint32_t>> groupTasks;
 std::set<std::tuple<uint32_t,uint32_t,uint32_t>> feedbackSeen;uint64_t feedback=0;std::ofstream events,wire;
 struct Counts {uint64_t consumed=0,returned=0,peak=0;};std::map<std::pair<uint32_t,uint32_t>,Counts> counts;
 Ptr<UbController> C(uint32_t n){return nodes[n]->GetObject<UbController>();}
 void Event(std::string name,uint32_t group=0,uint32_t task=0,uint32_t node=0,uint32_t off=0,uint32_t len=0){events<<Simulator::Now().GetPicoSeconds()<<','<<name<<','<<group<<','<<task<<','<<node<<','<<off<<','<<len<<'\n';events.flush();}
 void Pair(uint32_t src,uint32_t dst,uint32_t a,uint32_t b,Ptr<UbTransportChannel>& tx,Ptr<UbTransportChannel>& rx){Connection c;c.ownerNodeId=src;c.node1=src;c.node2=dst;c.port1=c.port2=0;c.tpn1=a;c.tpn2=b;c.priority=7;c.metrics=0;
  C(src)->GetTpConnManager()->AddUnilateralConnection(c,src);C(dst)->GetTpConnManager()->AddUnilateralConnection(c,dst);
  C(src)->GetTransportChannelManager()->CreateTp(src,dst,0,0,7,a,b,UbCongestionControl::Create(UB_DEVICE));C(dst)->GetTransportChannelManager()->CreateTp(dst,src,0,0,7,b,a,UbCongestionControl::Create(UB_DEVICE));tx=C(src)->GetTransportChannelManager()->GetTp(a);rx=C(dst)->GetTransportChannelManager()->GetTp(b);
 }
 void Add(uint32_t id,uint32_t src,std::vector<uint32_t> ranks){std::vector<lightweight::GroupManager::Member> members;payload[id].resize(bytes);for(uint32_t i=0;i<bytes;++i)payload[id][i]=uint8_t((id*73+i*131+(i>>8)*17)%251);
  for(auto dst:ranks){uint32_t task=id*10+dst,a=task*2,b=a+1,jid=task;Child c{task,id,src,dst,jid};Pair(src,dst,a,b,c.tx,c.rx);C(src)->GetUbFunction()->CreateJetty(src,dst,jid);NS_ABORT_MSG_IF(!C(src)->GetUbTransaction()->JettyBindTp(src,dst,jid,false,{a}),"bind");c.jetty=C(src)->GetUbFunction()->GetJetty(jid);c.jetty->SetTaSegmentBytes(1024);c.data.resize(bytes);children.emplace(task,std::move(c));groupTasks[id].push_back(task);auto& child=children.at(task);
   child.jetty->SetClientCallback(Callback<void,uint32_t,uint32_t>([this](uint32_t task,uint32_t jetty){auto& c=children.at(task);NS_ABORT_MSG_IF(c.jid!=jetty||!c.ready||c.done,"early/duplicate child completion");c.done=true;Event("sender_complete",c.group,task,c.src);manager.Completed(task);}));
   child.tx->TraceConnectWithoutContext("WqeSegmentSendsNotify",Callback<void,uint32_t,uint32_t,uint32_t>([this,task](uint32_t,uint32_t tid,uint32_t ssn){auto& c=children.at(task);NS_ABORT_MSG_IF(tid!=task||c.admitted>=bytes||!c.offsets.emplace(ssn,c.admitted).second,"admission identity");auto off=c.admitted;c.admitted+=std::min(1024u,bytes-off);Event("ta_admitted",c.group,task,c.src,off,c.admitted-off);manager.Refresh(c.src);}));
   members.push_back({dst,task,child.tx,child.rx});
  }
  manager.Add(id,src,bytes,1024,DynamicCast<UbPort>(nodes[src]->GetDevice(0)),members);manager.groups.at(id).queue->grantObserver=[this,src](uint32_t group,bool control){Event(control?"control_grant":"data_grant",group,0,src);};
 }
 void Submit(uint32_t id){manager.Start(id);auto& g=manager.groups.at(id);Event("group_submit",id,0,g.source,0,bytes);for(auto task:groupTasks.at(id)){auto& c=children.at(task);auto w=C(c.src)->GetUbFunction()->CreateWqe(c.src,c.dst,bytes,task,UbTransactionOpcode::WRITE);w->SetExplicitPayload(Create<Packet>(payload.at(id).data(),bytes));NS_ABORT_MSG_IF(C(c.src)->GetUbFunction()->SubmitWqe(w,c.jid).status!=UbWqeSubmissionStatus::ACCEPTED,"submit");}manager.Refresh(g.source);}
 void Receive(uint32_t node,Ptr<UbPort> port,Ptr<Packet> packet){auto sw=nodes[node]->GetObject<UbSwitch>();if(sw->GetPacketTypeForTest(packet)==UB_URMA_DATA_PACKET){auto copy=packet->Copy();UbDatalinkPacketHeader dl;UbIpBasedNetworkHeader net;Ipv4Header ip;UdpHeader udp;UbTransportHeader h;copy->RemoveHeader(dl);copy->RemoveHeader(net);copy->RemoveHeader(ip);copy->RemoveHeader(udp);copy->RemoveHeader(h);
   if(!UbTransportChannel::IsTransportResponseOpcode(h.GetTPOpcode())){UbTransportChannel::ReceivedDataPacketContext ctx;NS_ABORT_MSG_IF(!children.begin()->second.tx->ParseReceivedDataPacketForTest(packet->Copy(),ctx),"decode");if(ctx.transactionHeader.GetUbTransactionOpcode()==uint8_t(UbTransactionOpcode::TAACK)){
    if(!injected&&!fault.empty()){injected=true;Event("fault",0,ctx.flowTag.GetFlowId(),node);if(fault=="missing")return;if(fault=="duplicate"){Receive(node,port,packet->Copy());Receive(node,port,packet->Copy());return;}if(fault=="wrong-task"){UbFlowTag old;packet->RemovePacketTag(old);packet->AddPacketTag(UbFlowTag(0,bytes));Receive(node,port,packet);return;}if(fault=="wrong"){h.SetSrcTpn(999);copy->AddHeader(h);copy->AddHeader(udp);copy->AddHeader(ip);copy->AddHeader(net);copy->AddHeader(dl);Receive(node,port,copy);return;}}
    auto tid=ctx.flowTag.GetFlowId();++feedback;Event("feedback",children.count(tid)?children.at(tid).group:0,tid,node,h.GetPsn(),packet->GetSize());
   }}
  }manager.ReceiveNative(node,port,packet);
 }
 void Init(){GlobalValue::Bind("UB_CC_ENABLED",BooleanValue(false));utils::UbUtils::Get();for(auto key:{"UB_TRACE_ENABLE","UB_PACKET_TRACE_ENABLE","UB_PORT_TRACE_ENABLE","UB_RECORD_PKT_TRACE"})GlobalValue::Bind(key,BooleanValue(false));Config::SetDefault("ns3::UbTransportChannel::DefaultMaxInflightPacketSize",UintegerValue(window));Config::SetDefault("ns3::UbTransportChannel::DefaultMaxWqeSegNum",UintegerValue(1000));Config::SetDefault("ns3::UbJetty::UbJettyInflightMax",UintegerValue(512));
  if(pressure){UbEgressQueue::GetTypeId();Config::SetDefault("ns3::UbEgressQueue::MaxEgressBytes",UintegerValue(1600));Config::SetDefault("ns3::UbPort::CbfcCtrlCrdRtrThldCell",IntegerValue(1));}
  for(uint32_t n=0;n<6;++n){auto node=CreateObject<Node>();nodes.push_back(node);auto sw=CreateObject<UbSwitch>();node->AggregateObject(sw);sw->SetNodeType(n==5?UB_SWITCH:UB_DEVICE);if(n<5){auto c=CreateObject<UbController>();node->AggregateObject(c);c->CreateUbFunction();c->CreateUbTransaction();}if(pressure){sw->SetReservePerQueueBytes(1600);sw->SetCbfcCredits(10,0);sw->SetCbfcCellGeometry(20,8);sw->SetCbfcReturnCellGrain(1,1);}for(uint32_t p=0;p<(n==5?5:1);++p){auto port=CreateObject<UbPort>();port->SetAddress(Mac48Address::Allocate());port->SetAttribute("UbDataRate",DataRateValue(DataRate("100Gbps")));node->AddDevice(port);}sw->Init();UbCongestionControl::Create(UB_SWITCH)->OnSwitchAttached(sw);}
  for(uint32_t n=0;n<5;++n){auto link=CreateObject<UbLink>();link->SetAttribute("Delay",TimeValue(NanoSeconds(20)));DynamicCast<UbPort>(nodes[n]->GetDevice(0))->Attach(link);DynamicCast<UbPort>(nodes[5]->GetDevice(n))->Attach(link);}
  for(uint32_t n=0;n<6;++n)for(uint32_t d=0;d<5;++d)if(n!=d){uint16_t p=n==5?d:0;auto& t=nodes[n]->GetObject<UbSwitch>()->GetRoutingProcess()->GetRoutingTable();t.AddShortestRoute(NodeIdToIp(d).Get(),{p});t.AddShortestRoute(NodeIdToIp(d,0).Get(),{p});}nodes[5]->GetObject<UbSwitch>()->EnableNetworkReplication({0,1,2,3,4});
  if(scenario=="capacity")manager.limit=1;Add(1001,0,scenario=="oversize"?std::vector<uint32_t>{1,2,3,4}:std::vector<uint32_t>{1,2});Add(1002,scenario=="different-source"?4:0,{2,3});if(scenario=="dynamic")Add(1003,0,{1,3});
  manager.onComplete=[this](uint32_t id){Event("group_complete",id,0,manager.groups.at(id).source);};
  for(uint32_t n=0;n<5;++n){auto sw=nodes[n]->GetObject<UbSwitch>();sw->EnableNetworkSink(n,Callback<void,uint32_t,uint32_t,Ptr<Packet>>([this,n](uint32_t g,uint32_t seq,Ptr<Packet> p){manager.Receive(n,g,seq,p);}));auto port=DynamicCast<UbPort>(nodes[n]->GetDevice(0));port->SetReceiveHandler(Callback<void,Ptr<UbPort>,Ptr<Packet>>([this,n](Ptr<UbPort> p,Ptr<Packet> b){Receive(n,p,b);}));
   C(n)->GetUbTransaction()->SetTargetExecutor(UbTargetExecutor([this,n](Ptr<const UbWqeSegment> req,const UbTransactionRule&,UbTargetCompletion done){auto tid=req->GetTaskId();NS_ABORT_MSG_IF(!children.count(tid),"target task");auto& c=children.at(tid);auto ssn=req->GetTaSsn();NS_ABORT_MSG_IF(c.dst!=n||c.src!=req->GetSrc()||c.jid!=req->GetJettyNum()||!c.offsets.count(ssn)||!c.seen.insert(ssn).second,"target ownership");auto off=c.offsets.at(ssn),len=req->GetPayloadBytes();NS_ABORT_MSG_IF(len!=std::min(1024u,bytes-off),"target length");std::vector<uint8_t> b(len);req->GetExplicitPayload()->CopyData(b.data(),len);NS_ABORT_MSG_IF(!std::equal(b.begin(),b.end(),payload.at(c.group).begin()+off),"payload");std::copy(b.begin(),b.end(),c.data.begin()+off);
    auto complete=[this,tid,off,len,done]{auto& c=children.at(tid);done(UbWorkExecutionResult{});c.covered+=len;Event("target_complete",c.group,tid,c.dst,off,len);NS_ABORT_MSG_IF(c.covered>bytes,"overcoverage");if(c.covered==bytes){c.ready=true;Event("receiver_ready",c.group,tid,c.dst);}};if(scenario=="window"&&c.group==1001)Simulator::Schedule(NanoSeconds(1000),complete);else complete();
   }));
  }
  for(uint32_t n=0;n<6;++n)for(uint32_t p=0;p<nodes[n]->GetNDevices();++p){auto port=DynamicCast<UbPort>(nodes[n]->GetDevice(p));auto record=[this,n,p](std::string ev,Ptr<Packet> packet){auto& s=counts[{n,p}];auto sw=nodes[n]->GetObject<UbSwitch>();UbNetworkReplicationTag tag;bool env=packet->PeekPacketTag(tag)&&tag.nativeEnvelope;bool credit=!env&&sw->GetPacketTypeForTest(packet)==UB_CONTROL_FRAME;if(!credit){if(ev=="tx")s.consumed+=(packet->GetSize()+159)/160;else s.returned+=(packet->GetSize()+159)/160;}wire<<Simulator::Now().GetPicoSeconds()<<','<<ev<<','<<n<<','<<p<<','<<packet->GetSize()<<','<<(env?tag.object:0)<<','<<(env?tag.sequence:0)<<','<<(credit?"credit":env?"envelope":"native")<<'\n';};
   port->TraceConnectWithoutContext("TraComEventNotify",Callback<void,Ptr<Packet>,Time>([record](Ptr<Packet> b,Time){record("tx",b);}));port->TraceConnectWithoutContext("PktRcvNotify",Callback<void,Ptr<Packet>>([record](Ptr<Packet> b){record("rx",b);}));port->GetUbQueue()->TraceConnectWithoutContext("UbEnqueue",Callback<void,Ptr<const Packet>,uint32_t>([this,n,p](Ptr<const Packet>,uint32_t used){counts[{n,p}].peak=std::max(counts[{n,p}].peak,uint64_t(used));}));}
 }
 void Run(){std::filesystem::create_directories(out);events.open(out+"/events.csv");wire.open(out+"/wire.csv");events<<"time_ps,event,group,task,node,offset,bytes\n";wire<<"time_ps,event,node,port,bytes,group,sequence,kind\n";Init();manager.CheckCapacity(nodes);Simulator::Schedule(NanoSeconds(100),[this]{Submit(1001);Submit(1002);});if(scenario=="dynamic")Simulator::Schedule(NanoSeconds(500),[this]{Submit(1003);});Simulator::Stop(MilliSeconds(10));Simulator::Run();manager.CheckDrained();
  std::ofstream summary(out+"/groups.csv");summary<<"group,source,fanout,payload_bytes,wire_bytes,envelopes,window_waits,members\n";for(auto&[id,g]:manager.groups){summary<<id<<','<<g.source<<','<<g.members.size()<<','<<g.queue->payloadSent<<','<<g.queue->wireDataBytes<<','<<g.queue->envelopes<<','<<g.queue->windowWaits<<',';for(auto& m:g.members)summary<<m.rank<<':'<<m.task<<';';summary<<'\n';}
  for(auto&[task,c]:children){NS_ABORT_MSG_IF(!c.done||!c.ready||c.covered!=bytes||c.data!=payload.at(c.group)||!c.jetty->IsIdle(),"child final state");std::ofstream f(out+"/payload-"+std::to_string(task)+".bin",std::ios::binary);f.write((char*)c.data.data(),c.data.size());}
  uint64_t blocked=0;std::ofstream ports(out+"/ports.csv");ports<<"node,port,peak,consumed,returned,restored,free,pending,blocked\n";
  for(uint32_t n=0;n<6;++n)for(uint32_t p=0;p<nodes[n]->GetNDevices();++p){auto port=DynamicCast<UbPort>(nodes[n]->GetDevice(p));auto fc=DynamicCast<UbCbfc>(port->GetFlowControl());auto s=counts[{n,p}];NS_ABORT_MSG_IF(fc->GetConsumedCells()!=s.consumed||fc->GetReturnedCells()!=s.returned||int64_t(pressure?10:6553)-int64_t(fc->GetConsumedCells())+int64_t(fc->GetRestoredCells())!=fc->GetTxFreeCells(7)||port->GetUbQueue()->GetCurrentBytes()||s.peak>(pressure?1600:524288),"port conservation");blocked+=fc->GetBlockedQueryCount();ports<<n<<','<<p<<','<<s.peak<<','<<s.consumed<<','<<s.returned<<','<<fc->GetRestoredCells()<<','<<fc->GetTxFreeCells(7)<<','<<fc->GetCrdToReturn(7)<<','<<fc->GetBlockedQueryCount()<<'\n';}
  NS_ABORT_MSG_IF(pressure&&!blocked,"pressure not exercised");auto sw=nodes[5]->GetObject<UbSwitch>();auto s=sw->GetNetworkReplicationStats();NS_ABORT_MSG_IF(s.admitted!=s.released||s.branches!=s.branchDequeues||s.parentBytes||s.branchBytes||s.descriptors||sw->GetQueueManager()->GetSwitchBufferOccupancy().total_buffered_bytes,"switch drain");std::ofstream ok(out+"/summary.json");ok<<"{\"status\":\"PASS\",\"groups\":"<<manager.groups.size()<<",\"feedback\":"<<feedback<<",\"blocked\":"<<blocked<<"}\n";events.close();wire.close();Simulator::Destroy();
 }
};
int main(int argc,char**argv){Time::SetResolution(Time::PS);Test t;CommandLine c;c.AddValue("out","Private output",t.out);c.AddValue("scenario","same-source/different-source/dynamic/window",t.scenario);c.AddValue("bytes","Payload bytes",t.bytes);c.AddValue("window","TP packet window",t.window);c.AddValue("pressure","CBFC pressure",t.pressure);c.AddValue("fault","Feedback fault",t.fault);c.Parse(argc,argv);NS_ABORT_MSG_IF(t.out.empty()||!t.bytes||t.bytes>1048576||t.bytes%1024||!t.window,"config");t.Run();}
